# ---------------------------------------------------------------------------
# Canonical JSON and hashing (D07/D08/worker_01 conventions)
# ---------------------------------------------------------------------------
def _hydrate_spec(spec: dict[str, Any]) -> dict[str, Any]:
    """Fill fields derived by documented synthetic naming conventions so the
    embedded table stays compact. Every value is a pure function of idx.

    Normalizes tuple facts to their full contract shape:
      * risk rows gain the public_r4_risk_identity element (r[8]) when absent
        (default identity derived from the member id, matching the catalog
        generator's naming convention);
      * coverage rows gain the accepted_current element when absent (default
        True);
      * gap rows gain the visit/time-anchor element (g[6]) when absent
        (default a resolvable anchor date).
    """
    idx = spec["idx"]
    out = dict(spec)
    out.setdefault("site", SITE_REF)
    out.setdefault("def_id", f"SYN-D09-DEF-{idx:03d}")
    out.setdefault("aud_scope", f"SYN-D09-AUD-{idx:03d}")
    out.setdefault("stratum_contract", f"SYN-D09-SC-{idx:03d}")
    out.setdefault("ce_rules", [])
    out.setdefault("ce_refs", [])
    out.setdefault("design_clause_ref", None)
    out.setdefault("revisions", [])
    out.setdefault("rev_hashes", [])
    risks: list[list[Any]] = []
    for row in out.get("risks", []):
        r = list(row)
        if len(r) == 8:
            member_no = r[0].rsplit("-", 1)[-1]
            r.append(f"SYN-D09-RISKID-{idx:03d}-{member_no}")
        risks.append(r)
    out["risks"] = risks
    out["cov"] = [list(c) if len(c) == 4 else list(c) + [True]
                  for c in out.get("cov", [])]
    out["gaps"] = [list(g) if len(g) == 7 else list(g) + [["2026-02-01"]]
                   for g in out.get("gaps", [])]
    out["evidence"] = member_locators(out)
    # -- resolved domain facts (worker_01 corrective pass 2026-08-15) --
    out.setdefault("authority_validity", "valid")
    rules = SYNTHETIC_MODE_CONTRACT_NUMERIC_AUTHORITY
    out.setdefault(
        "min_count",
        rules["minimum_member_subject_count"]
        if out.get("kind") == "repeated_subject_risk" else None,
    )
    out.setdefault(
        "gap_positive_minimum",
        rules["gap_positive_minimum_opportunity_count"]
        if out.get("kind") == "systematic_data_or_process_gap" else None,
    )
    out.setdefault(
        "trend_positive_minimum",
        rules["trend_positive_minimum_subject_count"]
        if out.get("kind") == "within_site_time_trend" else None,
    )
    out.setdefault("method_validity", "valid")
    out.setdefault("signal_role", "none")
    out.setdefault("expansion", "not_applicable")
    n_wins = len(out["wins"])
    out.setdefault("win_rule_versions", [f"rule-version-{idx}" for _ in range(n_wins)])
    out.setdefault("stratum_method_versions", [f"method-version-{idx}" for _ in range(n_wins)])
    out.setdefault("lineage_relation", "none")
    out.setdefault("carry_forward_state", "none")
    out.setdefault("prior_risk_ref", None)
    out.setdefault("prior_identity_ref", None)
    out.setdefault("site_identity_state", "stable")
    out.setdefault("query_decision", "site_process_delta_present")
    out.setdefault("query_fanout", 100)
    out.setdefault("verification_states", ["verified"] * len(out["revisions"]))
    out.setdefault("risk_resolutions", ["locatable"] * len(out["risks"]))
    out.setdefault("gap_anchor_states", ["resolved"] * len(out["gaps"]))
    return out


def normalize_value(value: Any) -> Any:
    if isinstance(value, str):
        return unicodedata.normalize("NFC", value)
    if isinstance(value, dict):
        return {normalize_value(k): normalize_value(item) for k, item in value.items()}
    if isinstance(value, list):
        return [normalize_value(item) for item in value]
    return value


def canonical_json(value: Any) -> str:
    return json.dumps(
        normalize_value(value), ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), allow_nan=False,
    )


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def content_hash(obj: dict[str, Any], own_hash_key: str = "content_hash") -> str:
    core = {key: item for key, item in obj.items() if key != own_hash_key}
    return sha256_text(canonical_json(core))


def normalize_contract(text: str) -> str:
    return unicodedata.normalize("NFC", text.replace("\r\n", "\n").replace("\r", "\n"))


def validate_contract() -> str:
    """Verify the frozen contract file bytes/semantic SHA-256 (read-only)."""
    raw = CONTRACT.read_bytes()
    if sha256_bytes(raw) != CONTRACT_SEMANTIC_HASH:
        raise SystemExit(f"contract file SHA mismatch: {CONTRACT}")
    semantic = sha256_text(normalize_contract(raw.decode("utf-8")))
    if semantic != CONTRACT_SEMANTIC_HASH:
        raise SystemExit(f"contract semantic SHA mismatch: {semantic}")
    return semantic


# ---------------------------------------------------------------------------
# Decision engine: disposition from explicit spec facts + contract rules
# ---------------------------------------------------------------------------
def _sorted_unique(values: list[str]) -> list[str]:
    return sorted(set(values))


def ce_level_of(spec: dict[str, Any]) -> str:
    """Counterevidence explanation level derived from declared vs matched
    counterevidence rule refs (contract §3.2 input facts)."""
    declared = list(spec.get("ce_rules") or [])
    matched = list(spec.get("ce_refs") or [])
    if not declared:
        return "condition_absent"
    if not matched:
        return "none"
    if set(matched) == set(declared):
        return "full"
    return "partial"


def deep_link_deficient(spec: dict[str, Any]) -> bool:
    """No locatable one-hop source jump target (contract §11): an unresolved
    member source locator or an unresolved gap visit/time anchor (both
    explicit closed typed facts)."""
    if any(state != "locatable" for state in spec["risk_resolutions"]):
        return True
    if any(state != "resolved" for state in spec["gap_anchor_states"]):
        return True
    return False


def derive_disposition(spec: dict[str, Any]) -> tuple[str, str, dict[str, Any]]:
    """Return (disposition, primary_reason, extra) from contract §8/§9 rules.

    extra may carry zero_unit / gate / pair_state for control-plane cases.

    Every decisive branch consumes explicit closed typed facts of the spec
    row (coverage, source-verification states, authority validity, method
    validity, statistical-signal role/expansion, lineage context, member
    origin/cutoff relations, locator/anchor resolution states, query
    redundancy decision); no audit metadata, sentinel spelling or hash
    recipe is read here (worker_01 corrective pass 2026-08-15).
    """
    kind = spec["kind"]

    # -- zero-unit control-plane paths (contract §3.3, §8.1, §15) --
    if spec["es_state"] != "admitted":
        return "not_applicable", "routed_or_gated", {
            "zero_unit": True, "gate": spec["gate_kind"] or spec["es_state"],
        }
    if kind == "within_site_time_trend":
        n_win = len(spec["wins"])
        win_kinds = {w[2] for w in spec["wins"]}
        if n_win < 2:
            return "not_applicable", "window_pair_gate", {
                "zero_unit": True, "gate": "window_pair_gate",
                "pair_state": "insufficient_windows",
            }
        if len(win_kinds) > 1:
            return "not_applicable", "window_pair_gate", {
                "zero_unit": True, "gate": "window_pair_gate",
                "pair_state": "incomparable_windows",
            }

    # -- admitted-unit integrity gates (contract §8.2 order 1-6) --
    if spec["cutoff_state"] == "conflict":
        return "not_evaluable", "cutoff_conflict", {}
    required = set(spec["producers"])
    cov_by = {d: (l0, l1, accepted) for d, l0, l1, accepted in spec["cov"]}
    for domain in sorted(required):
        l0, l1, accepted = cov_by.get(domain, ("missing", "missing", True))
        if l0 != "covered" or l1 != "complete":
            return "not_evaluable", "coverage_hole", {"domain": domain}
        if not accepted:
            return "not_evaluable", "producer_ref_unresolvable", {}
    if any(state != "verified" for state in spec["verification_states"]):
        return "not_evaluable", "source_hash_mismatch", {}
    if spec["stratum_admission"] == "rejected_empty":
        return "not_evaluable", "stratum_required_empty", {}
    if spec["authority_validity"] == "invalid":
        return "not_evaluable", "authority_fail", {}
    if spec.get("design_clause_ref"):
        return "not_applicable", "design_not_applicable", {}
    if spec["den_state"] == "unclosed":
        return "not_evaluable", "denominator_unclosed", {}
    if spec["den_state"] == "closed_zero":
        return "not_evaluable", "denominator_closed_zero", {}
    if spec["opp_prov"] in ("raw_listing_only", "enumeration_conflict"):
        return "not_evaluable", "opportunity_provenance", {}
    if spec["opp_state"] == "unknown":
        return "not_evaluable", "opportunity_unknown", {}
    origins = {r[5] for r in spec["risks"]}
    if "wrong_scope" in origins:
        return "not_evaluable", "origin_wrong_scope", {}
    if "not_evaluable" in origins:
        return "not_evaluable", "origin_not_evaluable", {}
    if "ambiguous" in origins:
        return "boundary", "origin_ambiguous", {}
    # Contract §7.3: blinded project + treatment-group/role stratum key.
    if (spec["blind"] == "blinded"
            and spec["stratum_key"] in TREATMENT_STRATUM_KEYS):
        return "not_evaluable", "blinded_stratum_rejected", {}
    # Contract §7.2: merged/split center identity is never comparable.
    if spec["site_identity_state"] in ("merged", "split"):
        return "not_evaluable", "site_merge_split", {}
    # Contract §7.3: method validity preconditions not satisfied.
    if spec["method_validity"] == "insufficient":
        return "not_evaluable", "validity_insufficient", {}
    # Contract §11: unresolved locator/anchor -> no fabricated jump.
    if deep_link_deficient(spec):
        return "boundary", "deep_link_deficient", {}
    # Contract §7.3: hidden/visible rate mix -> qualified display.
    if spec["rate_state"] == "qualified":
        return "boundary", "visibility_qualified", {}

    # -- kind-specific medical rules (contract §9) --
    if kind == "repeated_subject_risk":
        true_cut = [r[6] for r in spec["risks"]]
        if true_cut and all(c == "out_of_cutoff" for c in true_cut):
            return "not_evaluable", "cutoff_all_out", {}
        if any(c == "spans_cutoff" for c in true_cut):
            return "boundary", "cutoff_spans", {}
        if any(c == "time_missing_not_evaluable" for c in true_cut):
            return "not_evaluable", "time_missing", {}
        in_subjects = {r[1] for r, c in zip(spec["risks"], true_cut) if c == "in_cutoff"}
        if len(in_subjects) == 0:
            return "negative", "closed_zero_no_members", {}
        min_count = spec["min_count"]
        if min_count is None:
            raise ValueError("resolved minimum_member_subject_count required")
        if len(in_subjects) < min_count:
            return "boundary", "n1_minimum", {}
        level = ce_level_of(spec)
        if level == "full":
            return "negative", "counterevidence_explains", {}
        if level == "partial":
            return "boundary", "counterevidence_partial", {}
        if spec["lineage_relation"] == "superseded_by_rule_or_method_change":
            return "boundary", "rule_supersession", {}
        if spec["signal_role"] == "sole_evidence":
            return "boundary", "statistics_only", {}
        if spec["expansion"] == "unexpandable":
            return "boundary", "signal_unexpandable", {}
        if spec["den_kind"] in ("subject_time", "exposure_time"):
            return "boundary", "short_exposure", {}
        if any(w[3] == "site_activation" for w in spec["wins"]):
            return "boundary", "late_activation", {}
        return "positive", "min_member_subject_count_satisfied", {}

    if kind == "systematic_data_or_process_gap":
        semantic_missing = 0 if ce_level_of(spec) == "full" else len(spec["gaps"])
        if spec["opp_state"] == "insufficient":
            if len(spec["gaps"]) > 0:
                return "boundary", "opportunity_insufficient", {}
            return "not_evaluable", "opportunity_insufficient", {}
        if semantic_missing == 0:
            return "negative", "closed_zero_no_members", {}
        minimum = spec["gap_positive_minimum"]
        if minimum is None:
            raise ValueError("resolved gap positive minimum required")
        if spec["opp_exp"] < minimum:
            return "boundary", "small_sample", {}
        return "positive", "accepted_gap_opportunity_sufficient", {}

    if kind == "within_site_time_trend":
        if not spec["chgs"]:
            return "negative", "closed_zero_no_members", {}
        comps = {c[3] for c in spec["chgs"]}
        change_kinds = {c[2] for c in spec["chgs"]}
        if "not_evaluable" in comps or "not_comparable" in change_kinds:
            # Contract §7.2/§7.3: incomparable windows never show a false
            # improvement/deterioration; the reason is a resolved fact.
            if spec["method_validity"] == "insufficient":
                return "not_evaluable", "validity_insufficient", {}
            if spec["carry_forward_state"] == "active":
                return "not_evaluable", "carry_forward", {}
            if len(set(spec["win_rule_versions"])) > 1:
                return "boundary", "window_definition_change", {}
            if spec["lineage_relation"] == "superseded_by_rule_or_method_change":
                return "boundary", "rule_supersession", {}
            if len(set(spec["stratum_method_versions"])) > 1:
                return "not_evaluable", "stratum_change", {}
            return "boundary", "not_comparable", {}
        causes = {c[4] for c in spec["chgs"]}
        if causes & {"coverage", "denominator", "method", "rule_or_mapping", "mixed"}:
            return "boundary", "explained_change", {}
        n_subj = len({c[1] for c in spec["chgs"]})
        minimum = spec["trend_positive_minimum"]
        if minimum is None:
            raise ValueError("resolved trend positive minimum required")
        if n_subj < minimum:
            return "boundary", "small_sample", {}
        return "positive", "comparable_windows_change_ledger", {}

    raise ValueError(f"unknown pattern kind: {kind}")


def numerator(spec: dict[str, Any]) -> tuple[int, int, int, int]:
    """(individual_risk_count, affected_subjects, events, gap_opportunities).

    Contract §5.2: members dedup by (public_r4_risk_identity,
    subject_stable_id) when origin_decision=verified_same_origin (the D08-
    verified same-origin binding is an input fact); the in-cutoff filter
    applies to the deduped member set. Out-of-cutoff members are retained as
    context in individual_risk_count but never counted as affected/events.
    """
    kind = spec["kind"]
    if kind == "repeated_subject_risk":
        rows = spec["risks"]
        if any(r[5] == "verified_same_origin" for r in rows):
            seen: dict[tuple[str, str], list[Any]] = {}
            for r in rows:
                seen.setdefault((r[8], r[1]), r)
            deduped = list(seen.values())
            in_members = [(r[1], r[2]) for r in deduped if r[6] == "in_cutoff"]
            return (len(deduped), len({m[0] for m in in_members}),
                    len({m[1] for m in in_members}), 0)
        in_members = [(r[1], r[2]) for r in rows if r[6] == "in_cutoff"]
        return len(rows), len({m[0] for m in in_members}), len({m[1] for m in in_members}), 0
    if kind == "systematic_data_or_process_gap":
        return 0, len({g[1] for g in spec["gaps"]}), 0, len(spec["gaps"])
    if kind == "within_site_time_trend":
        return 0, len({c[1] for c in spec["chgs"]}), 0, 0
    return 0, 0, 0, 0


def member_locators(spec: dict[str, Any]) -> list[str]:
    out: list[str] = []
    for r in spec["risks"]:
        if r[7]:
            out.append(r[7])
    for g in spec["gaps"]:
        if g[5]:
            out.append(g[5])
    for ch in spec["chgs"]:
        if ch[5]:
            out.append(ch[5])
    return _sorted_unique(out)


def member_pairs(spec: dict[str, Any]) -> list[list[str]]:
    """Sorted [member_id, first_locator] pairs for source/trace leaves."""
    pairs: list[list[str]] = []
    for r in spec["risks"]:
        if r[7]:
            pairs.append([r[0], r[7]])
    for g in spec["gaps"]:
        if g[5]:
            pairs.append([g[0], g[5]])
    for ch in spec["chgs"]:
        if ch[5]:
            pairs.append([ch[0], ch[5]])
    return sorted(pairs, key=lambda p: (p[0], p[1]))


def member_count(spec: dict[str, Any]) -> int:
    return len(spec["risks"]) + len(spec["gaps"]) + len(spec["chgs"])


def stable_core(spec: dict[str, Any]) -> str:
    idx = spec["idx"]
    window_stable = spec["wins"][-1][0] if spec["wins"] else f"SYN-D09-WIN-{idx:03d}-1"
    stratum_contract = spec.get("stratum_contract") or f"SYN-D09-SC-{idx:03d}"
    return "|".join([PROJECT_REF, spec["site"], spec["def_id"], window_stable,
                     stratum_contract, spec["stratum_key"]])


def owner_domain(spec: dict[str, Any]) -> str:
    if spec["owner"] == "evaluate_and_own":
        return "D09"
    token = spec["token"]
    if token.startswith("d06_"):
        return "D06"
    if token.startswith("d10_"):
        return "D10"
    if token == "d01_d08_individual_fact":
        return "D01-D08"
    return "unresolved"


def query_generated(spec: dict[str, Any], disposition: str) -> bool:
    """Contract section 12: at most one Query draft per positive pattern unit,
    only when the redundancy decision allows it and the resolvable member
    list stays within the resolved fanout limit."""
    if disposition != "positive":
        return False
    if spec["query_decision"] != "site_process_delta_present":
        return False
    kind = spec["kind"]
    if kind == "repeated_subject_risk":
        member_count = len(spec["risks"])
    elif kind == "systematic_data_or_process_gap":
        member_count = len(spec["gaps"])
    else:
        member_count = len(spec["chgs"])
    return member_count <= spec["query_fanout"]


# ---------------------------------------------------------------------------
# Leaf builders
# ---------------------------------------------------------------------------
def build_expected_leaf_set(spec: dict[str, Any], disposition: str,
                            reason: str, extra: dict[str, Any]) -> dict[str, Any]:
    zero_unit = extra.get("zero_unit", False)
    unit_count = 0 if zero_unit else 1
    kind = spec["kind"]
    individual_risk, affected, events, gap_opps = numerator(spec)
    source_record_count = len(spec["evidence"])
    risk_count = 1 if disposition == "positive" else 0
    clue_count = 1 if disposition == "boundary" else 0
    query_count = 1 if query_generated(spec, disposition) else 0
    center_pattern_count = risk_count
    downstream_handoff = (disposition == "positive"
                          or spec["carry_forward_state"] == "active")
    l0_complete = all(
        l0 == "covered" for d, l0, l1, _accepted in spec["cov"] if d in set(spec["producers"]))
    domain_complete = all(
        l1 == "complete" for d, l0, l1, _accepted in spec["cov"] if d in set(spec["producers"]))
    opp_missing = max(0, spec["opp_exp"] - spec["opp_obs"])

    leaf: dict[str, Any] = {
        "all_units_disposed": True,
        "unit_count": unit_count,
        "positive_count": 1 if disposition == "positive" else 0,
        "negative_count": 1 if disposition == "negative" else 0,
        "boundary_count": 1 if disposition == "boundary" else 0,
        "not_applicable_count": 1 if disposition == "not_applicable" else 0,
        "not_evaluable_count": 1 if disposition == "not_evaluable" else 0,
        "expected_set_reconciled": True,
        "gate_count": 1 if (zero_unit and extra.get("gate")) else 0,
        "open_gate_count": 1 if (zero_unit and extra.get("gate")) else 0,
        "integrity.stage": spec["es_state"],
        "integrity.gate_kind": spec["gate_kind"] if spec["es_state"] != "admitted" else None,
        "integrity.error_object": None,
        "integrity.error_stage": None,
        "integrity.error_type": None,
        "l0_complete": l0_complete,
        "domain_complete": domain_complete,
        "l2.individual_risk_count": individual_risk if unit_count else 0,
        "l2.affected_subject_count": affected if (unit_count and disposition in ("positive", "boundary")) else 0,
        "l2.event_count": events if (unit_count and disposition in ("positive", "boundary")) else 0,
        "l2.gap_opportunity_count": gap_opps if (unit_count and disposition in ("positive", "boundary")) else 0,
        "l2.center_pattern_count": center_pattern_count,
        "l2.clue_count": clue_count,
        "l2.query_count": query_count,
        "l2.risk_count": risk_count,
        "l2.source_record_count": source_record_count,
        "l3.positive_count": risk_count,
        "l3.boundary_count": clue_count,
        "l3.risk_count": risk_count,
        "ownership.owner_domain": owner_domain(spec),
        "ownership.d09_action": spec["owner"],
        "ownership.risk_candidate_present": risk_count == 1,
        "ownership.risk_owner": "D09" if risk_count else None,
        "ownership.query_draft_present": query_count == 1,
        "ownership.query_owner": "D09" if query_count else None,
        "ownership.downstream_handoff_present": downstream_handoff,
        "ownership.handoff_target_domain": "R2" if downstream_handoff else None,
        "measure.denominator_kind": spec["den_kind"],
        "measure.denominator_value": spec["den_value"],
        "measure.denominator_state": spec["den_state"],
        "measure.opportunity_expected": spec["opp_exp"],
        "measure.opportunity_observed": spec["opp_obs"],
        "measure.opportunity_missing": opp_missing,
        "measure.opportunity_state": spec["opp_state"],
        "gate.window_pair_gate_present": extra.get("gate") == "window_pair_gate",
        "gate.window_pair_state": extra.get("pair_state"),
        "gate.admission_gate_present": spec["es_state"] != "admitted",
        "gate.admission_gate_kind": spec["gate_kind"] if spec["es_state"] != "admitted" else None,
    }
    if unit_count:
        leaf.update({
            "units.0.l1_disposition": disposition,
            "units.0.pattern_kind": kind,
            "units.0.unit_kind": "d09_pattern_unit",
            "units.0.primary_reason": reason,
            "units.0.participant_count": affected if disposition in ("positive", "boundary") else 0,
            "units.0.event_count": events if disposition in ("positive", "boundary") else 0,
            "units.0.gap_opportunity_count": gap_opps if disposition in ("positive", "boundary") else 0,
            "units.0.individual_risk_count": individual_risk,
            "units.0.risk_count": risk_count,
            "units.0.clue_count": clue_count,
            "units.0.query_count": query_count,
            "units.0.evidence_count": source_record_count,
            "units.0.counterevidence_count": len(spec["ce_refs"]),
            "units.0.gate_signal_type": None,
            "units.0.lineage_handoff": downstream_handoff,
            "units.0.stable_core": stable_core(spec),
        })
    return leaf


def build_source_leaf_set(spec: dict[str, Any], disposition: str) -> dict[str, Any]:
    evidence = spec["evidence"]
    hidden_member_ids = set(spec["hidden"])
    locator_by_member = {p[0]: p[1] for p in member_pairs(spec)}
    hidden_locators = _sorted_unique(
        locator_by_member[m] for m in hidden_member_ids if m in locator_by_member)
    projectable = _sorted_unique(loc for loc in evidence if loc not in set(hidden_locators))
    members = member_pairs(spec)
    reverse_binding = [p for p in members if p[1] in set(evidence)]
    journey = (any(r[0] for r in spec["risks"])
               or any(bool(g[6]) and state == "resolved"
                      for g, state in zip(spec["gaps"], spec["gap_anchor_states"]))
               or bool(spec["chgs"]))
    return {
        "source.audience_anchor": spec["aud_scope"],
        "source.audience_lexicon_ref": None,
        "source.audience_payload_present": True,
        "source.disclosure_leak_present": False,
        "source.evaluation_node_set": evidence,
        "source.projectable_node_set": projectable,
        "source.hidden_node_count": len(hidden_member_ids),
        "source.journey_marker_present": journey,
        "source.producer_binding_ids": _sorted_unique(["SYN-D09-LOC-CV-001"] * min(1, len(spec["cov"]))),
        "source.query_present": query_generated(spec, disposition),
        "source.risk_present": disposition == "positive",
        "source.reverse_binding_count": len(reverse_binding),
        "source.source_jump_target_pairs": members,
    }


def build_trace_leaf_set(spec: dict[str, Any], disposition: str) -> dict[str, Any]:
    idx = spec["idx"]
    zero_unit = disposition == "not_applicable" and (
        spec["es_state"] != "admitted"
        or (spec["kind"] == "within_site_time_trend" and
            (len(spec["wins"]) < 2 or len({w[2] for w in spec["wins"]}) > 1)))
    pairs = member_pairs(spec)
    evidence_set = set(spec["evidence"])
    edge_ids = [f"SYN-D09-EDGE-{idx:03d}-{n:02d}" for n in range(1, len(pairs) + 1)]
    bidirectional = [p for p in pairs if p[1] in evidence_set]
    all_members_locatable = all(state == "locatable"
                                  for state in spec["risk_resolutions"])
    positive_ok = True if disposition != "positive" else (
        all_members_locatable and len([p for p in pairs if p[1] in evidence_set]) == len(pairs))
    return {
        "trace.stable_core_count": 0 if zero_unit else 1,
        "trace.unit_stable_cores": [] if zero_unit else [stable_core(spec)],
        "trace.lineage_handoff_count": 1 if (
            disposition == "positive" or spec["carry_forward_state"] == "active") else 0,
        "trace.superseded_unit_count": 1 if spec["lineage_relation"] == (
            "superseded_by_rule_or_method_change") else 0,
        "trace.edge_set": edge_ids,
        "trace.bidirectional_join_count": len(bidirectional),
        "trace.negative_checked_edge_count": len(pairs) if disposition == "negative" else 0,
        "trace.positive_evidence_ok": positive_ok,
        "trace.reverse_conservation_ok": all_members_locatable,
    }


def build_expectation(spec: dict[str, Any]) -> dict[str, Any]:
    disposition, reason, extra = derive_disposition(spec)
    return {
        "case_id": spec["case_id"],
        "oracle_case_id": spec["oracle_case_id"],
        "fixture_id": spec["fixture_id"],
        "expected_leaf_set": build_expected_leaf_set(spec, disposition, reason, extra),
        "expected_source_leaf_set": build_source_leaf_set(spec, disposition),
        "expected_trace_leaf_set": build_trace_leaf_set(spec, disposition),
    }


# ---------------------------------------------------------------------------
# Assembly / validation / CLI
# ---------------------------------------------------------------------------
def assemble_oracle() -> dict[str, Any]:
    expectations = [build_expectation(_hydrate_spec(spec)) for spec in ORACLE_CASES]
    oracle: dict[str, Any] = {
        "artifact_kind": "independent_expected_outcome_oracle",
        "oracle_id": ORACLE_ID,
        "schema_version": SCHEMA_VERSION,
        "contract_semantic_hash": CONTRACT_SEMANTIC_HASH,
        "case_count": len(expectations),
        "ordered_expectations": expectations,
        "content_hash": "",
    }
    oracle["content_hash"] = content_hash(oracle, "content_hash")
    return oracle


def validate_oracle(oracle: dict[str, Any]) -> None:
    if sorted(oracle.keys()) != sorted(ORACLE_TOP_KEYS):
        raise SystemExit(f"oracle top-level key mismatch: {sorted(oracle.keys())}")
    if oracle["oracle_id"] != ORACLE_ID:
        raise SystemExit("oracle_id mismatch")
    if oracle["case_count"] != len(oracle["ordered_expectations"]):
        raise SystemExit("case_count mismatch")
    if oracle["case_count"] != len(ORACLE_CASES):
        raise SystemExit("case_count vs spec table mismatch")
    seen: set[str] = set()
    for entry in oracle["ordered_expectations"]:
        if sorted(entry.keys()) != sorted(ORDERED_EXPECTATION_KEYS):
            raise SystemExit(f"expectation key mismatch: {sorted(entry.keys())}")
        if entry["oracle_case_id"] in seen:
            raise SystemExit(f"duplicate oracle_case_id {entry['oracle_case_id']}")
        seen.add(entry["oracle_case_id"])
        for leaf_name in ("expected_leaf_set", "expected_source_leaf_set", "expected_trace_leaf_set"):
            if not isinstance(entry[leaf_name], dict) or not entry[leaf_name]:
                raise SystemExit(f"{entry['oracle_case_id']} {leaf_name} empty")
    if oracle["content_hash"] != content_hash(oracle, "content_hash"):
        raise SystemExit("oracle content_hash mismatch")
    # canonical form round-trip
    canonical = canonical_json(oracle)
    if canonical_json(json.loads(canonical)) != canonical:
        raise SystemExit("oracle JSON not canonical")


def render(verbose: bool = True) -> dict[str, Any]:
    def log(message: str) -> None:
        if verbose:
            print(message)

    validate_contract()
    oracle = assemble_oracle()
    validate_oracle(oracle)
    payload = canonical_json(oracle).encode("utf-8")
    ORACLE.write_bytes(payload)
    log(f"wrote {ORACLE} ({len(payload)} bytes, sha256 {oracle['content_hash']})")
    return oracle


def check(verbose: bool = True) -> int:
    def log(message: str) -> None:
        if verbose:
            print(message)

    validate_contract()
    first = assemble_oracle()
    validate_oracle(first)
    second = assemble_oracle()
    validate_oracle(second)
    a_bytes = canonical_json(first).encode("utf-8")
    b_bytes = canonical_json(second).encode("utf-8")
    if a_bytes != b_bytes:
        log("FAIL: two fresh generations are NOT byte-identical")
        return 1
    log("OK: two fresh generations are byte-identical")
    log(f"    sha256 {first['content_hash']}")
    if not ORACLE.exists():
        log(f"FAIL: oracle artifact missing at {ORACLE}")
        return 1
    on_disk = ORACLE.read_bytes()
    if on_disk != a_bytes:
        log("FAIL: on-disk oracle bytes differ from a fresh generation")
        return 1
    log("OK: on-disk oracle matches a fresh generation")
    loaded = json.loads(on_disk.decode("utf-8"))
    validate_oracle(loaded)
    log("OK: on-disk oracle validates (schema, bijection, canonical, hash)")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description="D09 expected-outcome oracle generator")
    parser.add_argument("mode", nargs="?", default="check",
                        choices=("generate", "check"),
                        help="generate: write oracle artifact; check: verify determinism")
    args = parser.parse_args()
    if args.mode == "generate":
        render(verbose=True)
        return 0
    return check(verbose=True)


if __name__ == "__main__":
    sys.exit(main())
